impl<'de> serde::Deserialize<'de> for Resource {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let value = <super::super::codec::Value as serde::Deserialize>::deserialize(deserializer)?;
        let mut path = super::super::codec::Path::root("Resource");
        let object =
            super::super::codec::expect_object(&value, &path).map_err(serde::de::Error::custom)?;
        super::super::codec::Json::from_json(object, &mut path).map_err(serde::de::Error::custom)
    }
}

/// Any resource kept as its complete JSON object, root-set types included.
///
/// Carries the resourceType and the complete JSON object of any resource, a
/// type of the root set included, so a Bundle entry or a contained resource can
/// relay another server's JSON beside typed entries. The encoder writes the
/// body with its values as given, a decimal in its lexical form, and its
/// members in sorted key order, because codec::Object is a BTreeMap. Decoding
/// yields the typed variant for every resource type the enabled features select
/// and this struct for any other, so for a root-set type the raw form is a
/// write-side carrier. Read raw JSON into the body through the Deserialize impl
/// of codec::Value, which keeps every number in the text the document carried.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct UnknownResource {
    /// The `resourceType` of the carried resource.
    pub resource_type: std::string::String,
    /// The complete JSON object, `resourceType` included, written with its
    /// values as given and its members in sorted key order.
    pub body: super::super::codec::Value,
}
